# Second pass (DECISIONS 2): fold near-duplicates so each entry yields a distinct image set.
DROP = {"ipl", "rha", "exion"}  # none on the site nor in his words (site-text hits were substrings)
MERGE = {"bodytite": "facetite", "endymed": "rf-microneedling", "hyperhidrosis": "miradry",
         "toxin-hyperhidrosis": "miradry", "emsculpt-medical": "emsculpt-neo", "oxylight": "led-light",
         "hyaluronic-serum": "skin-barrier", "scc": "bcc", "dysport-xeomin-daxxify": "neurotoxin",
         "toxin-chin": "toxin-dao"}
RENAME = {"facetite": "FaceTite, AccuTite and BodyTite", "rf-microneedling": "Radiofrequency tightening (RF microneedling, EndyMed, PelleFirm)",
          "miradry": "Underarm sweating: miraDry and toxin", "led-light": "LED and oxygen facials (OxyLight)",
          "skin-barrier": "Moisturizers, hyaluronic acid and the skin barrier", "bcc": "Basal and squamous cell carcinoma",
          "neurotoxin": "Neurotoxins (Botox, Dysport, Xeomin, Daxxify)", "toxin-dao": "Lower face toxin: mouth corners and chin (DAO, mentalis)"}
_by = {row[0]: list(row) for row in P}
for src, dst in MERGE.items():
    s, d = _by.pop(src), _by[dst]
    d[2] = d[2] + [s[1]] + s[2]          # aliases
    d[7] = list(dict.fromkeys(d[7] + s[7]))  # anatomy
    d[8] = d[8] or s[8]
    d[9] = d[9] + "|" + s[9]
    d[11] = d[11] + s[11][:1]
for k in DROP:
    _by.pop(k)
for k, v in RENAME.items():
    _by[k][1] = v

P = [tuple(_by[row[0]]) for row in P if row[0] in _by]

pages = {r["url"].rstrip("/").replace("https://www.drarielostad.com", SITE) for r in json.load(open(ROOT / "raw/site/pages.json", encoding="utf-8"))}
vids = [r for r in json.load(open(ROOT / "data/videos.json", encoding="utf-8")) if r.get("source") == "own"]

out, ids = [], set()
for (pid, name, aliases, cat, brand, maker, what, anat, path, rx, region, search) in P:
    assert pid not in ids, pid
    ids.add(pid)
    url = (SITE + path) if path else None
    on_site = bool(url and url.rstrip("/") in pages)
    pat = re.compile(rx, re.I)
    ment = [v["id"] for v in vids if pat.search((v.get("transcript") or "") + " " + (v.get("caption") or "") + " " + (v.get("title") or ""))]
    out.append({
        "id": pid, "name": name, "aliases": aliases, "category": cat,
        "brand_or_device": brand, "manufacturer": maker, "what_it_does": what,
        "anatomy": anat, "region": region, "mentioned_in": ment,
        "on_site": on_site, "site_url": url if on_site else None,
        "search_terms": [name.split(" (")[0]] + aliases[:3] + search,
    })

json.dump(out, open(ROOT / "refs/procedures.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
from collections import Counter
print(len(out), dict(Counter(p["category"] for p in out)))
print("no mention + not on site:", [p["id"] for p in out if not p["mentioned_in"] and not p["on_site"]])
